CREATE TABLE finance.channel_settlement (
 id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES org.company(id), review_document_id uuid NOT NULL, external_batch_id text NOT NULL, snapshot jsonb NOT NULL CHECK(jsonb_typeof(snapshot)='object'), created_by uuid NOT NULL REFERENCES org.principal(id), created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(company_id,id), UNIQUE(company_id,external_batch_id), UNIQUE(company_id,review_document_id), FOREIGN KEY(company_id,review_document_id) REFERENCES finance.workflow_document(company_id,id)
);
CREATE TABLE finance.channel_settlement_receipt (company_id uuid NOT NULL, settlement_id uuid NOT NULL, receipt_id uuid NOT NULL, PRIMARY KEY(company_id,settlement_id,receipt_id), UNIQUE(company_id,receipt_id), FOREIGN KEY(company_id,settlement_id) REFERENCES finance.channel_settlement(company_id,id), FOREIGN KEY(company_id,receipt_id) REFERENCES finance.receipt(company_id,id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['finance.channel_settlement','finance.channel_settlement_receipt'] LOOP EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t);EXECUTE format($p$CREATE POLICY company_scope ON %s USING(company_id=NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=NULLIF(current_setting('app.company_id',true),'')::uuid)$p$,t);EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON %s FOR EACH ROW EXECUTE FUNCTION pricing.reject_history_change()',t);EXECUTE format('GRANT SELECT,INSERT ON %s TO routefit_api',t);END LOOP;END $$;
